   "  const ids = names.map(n => bot.registry.blocksByName[n] && bot.registry.blocksByName[n].id).filter(x=>x!==undefined);",
   "  const start = inv(dropName);",
   "  let fails = 0, dug = 0;",
   "  const tried = new Set();",
   "  while (inv(dropName) < start + target && fails < 10) {",
   "    signal.check();",
   "    const block = bot.findBlock({ matching: ids, maxDistance: args.maxDistance || 32, useExtraInfo: b => !tried.has(b.position.toString()) });",
   "    if (!block) { log('mineBlocks: none found'); break; }",
   "    tried.add(block.position.toString());",
   "    try {",
   "      await bot.pathfinder.goto(new goals.GoalLookAtBlock(block.position, bot.world, { reach: 4 }));",
   "      const b = bot.blockAt(block.position);",
   "      if (!b || !ids.includes(b.type)) continue;",
   "      const tool = bot.pathfinder.bestHarvestTool(b);",
   "      if (tool) await bot.equip(tool, 'hand');",
   "      if (!b.canHarvest(bot.heldItem ? bot.heldItem.type : null)) { log('cannot harvest', b.name); fails++; continue; }",
   "      await bot.dig(b); dug++;",
   "      await sleep(250);",
   "      const drop = Object.values(bot.entities).find(e => e.name === 'item' && e.position.distanceTo(block.position) < 4);",
